package dev.epoch;

import dev.epoch.bridge.AutoRuntime;
import net.minecraft.client.gui.*;
import java.util.*;

public final class VersionListScreen extends GuiScreen {
 private List<AutoRuntime.Instance> entries=Collections.emptyList();private int first,rows;private long nextRefresh;private String error="",signature="";
 public boolean doesGuiPauseGame(){return false;}
 public void onGuiClosed(){ClientHooks.listClosed();}
 public void initGui(){reload();}
 private void reload(){entries=AutoRuntime.instances(mc.mcDataDir.toPath());signature=new com.google.gson.Gson().toJson(entries);rows=Math.max(1,(height-122)/40);first=Math.max(0,Math.min(first,Math.max(0,entries.size()-rows)));buttonList.clear();int w=Math.min(380,width-32),left=(width-w)/2;for(int i=first;i<entries.size()&&i<first+rows;i++){AutoRuntime.Instance e=entries.get(i);String label=e.label+" | "+e.version+" / Forge "+e.forgeVersion+(e.current?" [Current]":!e.supported?" [Unavailable]":"");GuiButton b=new GuiButton(100+2*i,left,48+(i-first)*40,w-86,20,fontRendererObj.trimStringToWidth(label,w-98));b.enabled=e.supported&&!e.current;buttonList.add(b);GuiButton warmup=new GuiButton(101+2*i,left+w-80,48+(i-first)*40,80,20,e.warmupLabel());warmup.enabled=e.canWarmup();buttonList.add(warmup);}GuiButton prev=new GuiButton(1,left,height-28,28,20,"<");prev.enabled=first>0;buttonList.add(prev);GuiButton next=new GuiButton(2,left+32,height-28,28,20,">");next.enabled=first+rows<entries.size();buttonList.add(next);buttonList.add(new GuiButton(3,width/2-45,height-28,90,20,"Refresh"));buttonList.add(new GuiButton(4,left+w-80,height-28,80,20,"Cancel"));nextRefresh=System.currentTimeMillis()+500;}
 protected void actionPerformed(GuiButton b){if(b.id==1)first-=rows;else if(b.id==2)first+=rows;else if(b.id==3){AutoRuntime.refresh(mc.mcDataDir.toPath());error="";}else if(b.id==4){mc.displayGuiScreen(null);return;}else if(b.id>=100){try{AutoRuntime.Instance entry=entries.get((b.id-100)/2);if((b.id-100)%2==0)ClientHooks.select(entry.id);else{AutoRuntime.warmup(mc.mcDataDir.toPath(),Epoch.VERSION,entry.id);error="";reload();}}catch(Exception e){error=e.getMessage();}return;}reload();}
 public void updateScreen(){if(System.currentTimeMillis()>=nextRefresh){nextRefresh=System.currentTimeMillis()+500;if(!signature.equals(new com.google.gson.Gson().toJson(AutoRuntime.instances(mc.mcDataDir.toPath()))))reload();}}
 public void handleMouseInput(){super.handleMouseInput();int wheel=org.lwjgl.input.Mouse.getEventDWheel();if(wheel!=0){first+=wheel>0?-1:1;reload();}}
 public void drawScreen(int x,int y,float partial){drawDefaultBackground();drawCenteredString(fontRendererObj,"Epoch - Switch version",width/2,14,0xF0F0EA);drawCenteredString(fontRendererObj,"Choose a local Forge instance",width/2,30,0xB8C1C8);int w=Math.min(380,width-32),left=(width-w)/2;for(int i=first;i<entries.size()&&i<first+rows;i++){AutoRuntime.Instance e=entries.get(i);String detail=e.detail();drawString(fontRendererObj,fontRendererObj.trimStringToWidth(detail==null?"Unavailable":detail,w),left+4,71+(i-first)*40,e.supported?0xB8C1C8:0xD4A080);}if(entries.isEmpty())drawCenteredString(fontRendererObj,"No local instances found. Use Refresh.",width/2,58,0xB8C1C8);String status=error.isEmpty()?AutoRuntime.statusText(mc.mcDataDir.toPath()):error;drawCenteredString(fontRendererObj,fontRendererObj.trimStringToWidth(status==null?"":status,width-24),width/2,height-55,error.isEmpty()?0xB8C1C8:0xF0A090);if(!entries.isEmpty())drawCenteredString(fontRendererObj,(first+1)+"-"+Math.min(entries.size(),first+rows)+" / "+entries.size(),width/2,height-42,0xB8C1C8);super.drawScreen(x,y,partial);}
}

